public identifierName lastValueElementName()
{
    identifierName ret = classStr(TFMDataSourceRecordQuery);
    return ret;
}

public void initParmDefault()

{
    Query query;
    QueryBuildDataSource    qbd;

    super();
    if (pds.PackedQuery != conNull())
    {
        queryRun = new QueryRun(pds.PackedQuery);
        return;
    }
    query = new Query();

    qbd = query.addDataSource(tableName2Id(pds.TableName));

    queryRun = new QueryRun(query);
}

    /// <summary>
    ///
    /// </summary>
    public void new(TFMPageDatasources	_pds)
    {

        pds = _pds;
		if (!pds)
        {
            Error("@TFM:NoDatasourcechosen");
        }
        super();
    }

public static void Main(Args _args)
{
    TFMDataSourceRecordQuery	recordQuery;
    FormRun						caller = _args.caller();
    FormDataSource				dataSourcesDS = caller.dataSource(tableStr(TFMPageDatasources));
    TFMPageDatasources			pds = dataSourcesDS.cursor();

    recordQuery = new TFMDataSourceRecordQuery(pds);

    if (recordQuery.prompt())
    {
        recordQuery.run();
    }
}

